package com.shopsphere.controller;
import com.shopsphere.dao.ProductDAO; import com.shopsphere.util.DB; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.IOException; import java.math.BigDecimal; import java.sql.*;
@WebServlet("/admin/*") public class AdminServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{q.setAttribute("products",new ProductDAO().findAll(""));try(Connection c=DB.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) users FROM users WHERE role='CUSTOMER'")){r.next();q.setAttribute("customers",r.getInt(1));}try(Connection c=DB.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) orders_count,COALESCE(SUM(total_amount),0) revenue FROM orders")){r.next();q.setAttribute("ordersCount",r.getInt(1));q.setAttribute("revenue",r.getBigDecimal(2));}q.getRequestDispatcher("/WEB-INF/views/admin.jsp").forward(q,p);}catch(Exception e){throw new ServletException("Admin dashboard failed",e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{String action=q.getParameter("action");if("add".equals(action)){String name=required(q,"name"),brand=required(q,"brand"),desc=required(q,"description"),priceText=required(q,"price"),stockText=required(q,"stock"),image=q.getParameter("imageUrl");BigDecimal price=new BigDecimal(priceText);int stock=Integer.parseInt(stockText);if(price.signum()<0||stock<0)throw new IllegalArgumentException("Price and stock cannot be negative.");new ProductDAO().add(0,name,brand,desc,price,stock,image==null?"":image);}else if("deactivate".equals(action)){new ProductDAO().setStatus(Long.parseLong(q.getParameter("productId")),false);}else if("activate".equals(action)){new ProductDAO().setStatus(Long.parseLong(q.getParameter("productId")),true);}p.sendRedirect(q.getContextPath()+"/admin?updated=1");}catch(Exception e){q.setAttribute("adminError",e.getMessage());doGet(q,p);}}
 private String required(HttpServletRequest q,String n){String v=q.getParameter(n);if(v==null||v.isBlank())throw new IllegalArgumentException("Please fill in all required product fields.");return v.trim();}
}
